@Component("transaction-handler")
@ProcessingGroup("transaction-processing-group")
public class TransactionEventHandler {
	
	// core constructor
	TransactionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTransactionEvent
     */
    @EventHandler
    public void handle( CreateTransactionEvent event) {
        entityManager.persist(new Transaction(event.getTransactionId(), event.getAmount(), event.getFee(), event.getExchangeRate(), event.getCreatedAt(), event.getCompletedAt(), event.getNarrative(), event.getAccount(), event.getWallet(), event.getPaymentOrder(), event.getMerchant(), event.getCard(), event.getRelatedTransactions(), event.getAlerts(), event.getTransactionType(), event.getStatus()));
    }

    /*
     * @param	event UpdateTransactionEvent
     */
    @EventHandler
    public Transaction handle( UpdateTransactionEvent event) {
    	entityManager.merge(new Transaction(event.getTransactionId(), event.getAmount(), event.getFee(), event.getExchangeRate(), event.getCreatedAt(), event.getCompletedAt(), event.getNarrative(), event.getAccount(), event.getWallet(), event.getPaymentOrder(), event.getMerchant(), event.getCard(), event.getRelatedTransactions(), event.getAlerts(), event.getTransactionType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteTransactionEvent
     */
    @EventHandler
    public void on( DeleteTransactionEvent event) {
    	Transaction entity = new Transaction();
   
    	// ------------------------------------------
    	// apply the TransactionId
    	// ------------------------------------------
    	entity.setTransactionId( event.getTransactionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TransactionRepository transactionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TransactionEventHandler.class.getName());

}
